      "mechanism": "The creature's foot is too short relative to leg length (foot_to_leg = 0.1129 vs reference 0.2667), reducing the capture region and causing forward falls.",
      "evidence": [
        "creature.features.foot_to_leg",
        "creature.reference.features.foot_to_leg",
        "baseline.capture_margin_over_leg_mean"
      ],
      "competing": [
        "The stride amplitudes are too small."
      ]
    },
    {
      "id": "H3",
      "mechanism": "The controller's placement feedback gains (fp_kd, fp_kv) are zero, preventing adaptive foot placement based on torso state, which is needed for this body.",
      "evidence": [
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.touchdown_foot_ahead_over_leg_last",
        "baseline.touchdown_foot_ahead_over_leg_last"
